mapper.sql:
WHERE d.company_id = #{f.companyId}
AND d.distributor_self = 0

	AND d.is_valid IN
	#{v}


	AND d.is_valid = #{f.isValid}


	AND d.is_valid = 'true'


	AND d.open_divided = #{f.openDivided}


	AND d.province LIKE CONCAT('%', #{f.provinceLikeEscaped}, '%') ESCAPE '\\'


	AND d.city LIKE CONCAT('%', #{f.cityLikeEscaped}, '%') ESCAPE '\\'


	AND d.area LIKE CONCAT('%', #{f.areaLikeEscaped}, '%') ESCAPE '\\'


	AND d.is_ziti = #{f.isZiti}


	AND d.is_delivery = #{f.isDelivery}


	AND d.is_dada = #{f.isDada}


	AND d.distributor_category_id = #{f.distributorCategoryIdEq}


	AND (d.shop_id IS NOT NULL AND d.shop_id <> 0 AND d.shop_id <> '')


	AND d.distributor_id IN
	#{id}


	AND d.distributor_id NOT IN
	#{xid}


	AND (
		d.name LIKE CONCAT('%', #{f.nameLikeEscaped}, '%') ESCAPE '\\'
		OR (

				d.distributor_id IN
				#{iid}


				1 = 0

		)
	)


	AND (
		d.name LIKE CONCAT('%', #{f.nameLikeEscaped}, '%') ESCAPE '\\'
		OR d.address LIKE CONCAT('%', #{f.nameLikeEscaped}, '%') ESCAPE '\\'
	)


	AND d.name LIKE CONCAT('%', #{f.nameLikeEscaped}, '%') ESCAPE '\\'

choose.when:
ORDER BY FIELD(distributor_id
,#{oid}
) ASC, distributor_id DESC

mapper.select:
SELECT * FROM (


		SELECT * FROM (
			SELECT d.*, m.merchant_name AS merchant_name,
				 AS distance


		) geo_filtered



		SELECT d.*, m.merchant_name AS merchant_name,
			 AS distance




		SELECT d.*, m.merchant_name AS merchant_name, CAST(NULL AS DECIMAL(18,10)) AS distance




) page_inner

LIMIT #{f.limit} OFFSET #{f.offset}
